answer:
结论：右边所有可能的排法就是 1~N 的全部合法出栈序列（把 Y 型铁轨的竖直段看作栈），总数为卡特兰数 C(2N,N)/(N+1)；例如 N=3 时共 5 种（123、132、213、231、321，312 非法）。
枚举与判定的完整程序如下（读入 N，按字典序输出全部合法序列）：
#include <stdio.h>

#define MAXN 12

static int n;
static int seq[MAXN];              /* 当前排列 */
static int used[MAXN];             /* 车厢是否已用 */

/* 判定 out 是否为 1..n 的合法出栈序列：栈模拟 */
static int valid(const int *out)
{
    int stack[MAXN], top = 0;
    int next = 1;                  /* 下一个待入栈车厢号 */
    for (int i = 0; i < n; i++)
    {
        while (next <= out[i])     /* 把 <= 当前输出值的车厢都压栈 */
            stack[top++] = next++;
        if (top > 0 && stack[top - 1] == out[i])
            top--;                 /* 栈顶正是当前车厢：弹出 */
        else
            return 0;              /* 否则该序列非法 */
    }
    return 1;
}

/* 回溯枚举 1..n 的所有排列，合法的按字典序输出 */
static void dfs(int pos)
{
    if (pos == n)
    {
        if (valid(seq))
        {
            for (int i = 0; i < n; i++)
                printf("%d%c", seq[i], i + 1 == n ? '\n' : ' ');
        }
        return;
    }
    for (int v = 1; v <= n; v++)
    {
        if (!used[v])
        {
            used[v] = 1;
            seq[pos] = v;
            dfs(pos + 1);
            used[v] = 0;
        }
    }
}

int main(void)
{
    printf("Input N (1-8): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 8)
        return 1;
    dfs(0);
    return 0;
}
要点：①合法性判定用栈模拟、O(N)；②全排列枚举 O(N!) 仅适合小 N，面试口答时可只给判定方法；③总数可用卡特兰数公式自检。

