struct node *reverse(struct node *head)
{
    struct node *p, *temp1, *temp2;
    if (head == NULL || head->next == NULL)
        return head;                 /* ① 空链表或单节点：直接返回 */
    p = head->next;
    head->next = NULL;               /* 原头成为逆置链表的尾 */
    while (p != NULL)                /* ② 还有未处理节点 */
    {
        temp1 = head;                /* 保存已逆置链表的旧头 */
        head = p;                    /* ③ 新头前移到当前节点 */
        temp2 = p;
        p = p->next;                 /* 先保存后继，再反转指针 */
        temp2->next = temp1;         /* ④ 当前节点接到旧头之前（头插） */
    }
    return head;
}
