void remove_node(struct node * *list, struct node *r, struct node *l)
{
    if (r == NULL) {
        *list = l->next;      /* ① 摘的是链头：头指针后移 */
    } else {
        r->next = l->next;    /* ② 前驱直接指向 l 的后继，跳过 l */
