answer:
两个完整实现如下（(a) Bresenham 画线，(b) 三点求圆心）：
#include <stdlib.h>

void DrawPixel(int x, int y, int pixColor);   /* 已有画点函数（由环境提供） */

/* (a) Bresenham 整数画线：任意方向、无浮点 */
void DrawLine(int x1, int y1, int x2, int y2, int pixColor) {
    int dx = abs(x2-x1), sx = x1<x2?1:-1;
    int dy = -abs(y2-y1), sy = y1<y2?1:-1;
    int err = dx+dy, e2;
    while (1) {
        DrawPixel(x1, y1, pixColor);
        if (x1==x2 && y1==y2) break;
        e2 = 2*err;
        if (e2 >= dy) { err += dy; x1 += sx; }
        if (e2 <= dx) { err += dx; y1 += sy; }
    }
}

/* (b) 求过三点 (x1,y1)(x2,y2)(x3,y3) 的圆心：两条垂直平分线联立求解；
       返回 0 成功、-1 三点共线（无外接圆） */
int CircleCenter(double x1, double y1, double x2, double y2,
                 double x3, double y3, double *cx, double *cy)
{
    double a1 = 2 * (x2 - x1), b1 = 2 * (y2 - y1);
    double c1 = x2 * x2 + y2 * y2 - x1 * x1 - y1 * y1;
    double a2 = 2 * (x3 - x1), b2 = 2 * (y3 - y1);
    double c2 = x3 * x3 + y3 * y3 - x1 * x1 - y1 * y1;
    double det = a1 * b2 - a2 * b1;
    if (det == 0) return -1;               /* 三点共线：无外接圆 */
    *cx = (c1 * b2 - c2 * b1) / det;       /* 克拉默法则 */
    *cy = (a1 * c2 - a2 * c1) / det;
    return 0;
}
要点：(a) 每步三选一（走 x、走 y 或对角），循环 O(|dx|+|dy|) 次、全整数；(b) O(1) 解线性方程组，det 为 0 要报错。

