/* (a) 定义寄存器变量：宏 + volatile 指针，32 位访问 */
#define REG_SER_TO_PAR (*(volatile unsigned int *)0x20000000)

/* (b) 读取效果说明：读取不会被挂起——内存映射寄存器读回的是引脚状态（Bit0/1/2 为
       SerIn/SerClk/ParClk 的回读或上次写入值），不属于异常中断源；
       具体读回值视硬件实现，可能为最后写入值 */

/* (c) 设置 bit1、保持其余位不变：按位或 */
void set_bit1(void) { REG_SER_TO_PAR |= (1 << 1); }

/* (d) 按 HwValue 置位/清位，其余位不变；先校验位号范围 */
void SysSetBit(unsigned char HwBit, unsigned char HwValue) {
    if (HwBit > 15) return;                    /* 位号超出有效范围：拒绝 */
    if (HwValue)
        REG_SER_TO_PAR |=  (1 << HwBit);       /* 置位 */
    else
        REG_SER_TO_PAR &= ~(1 << HwBit);       /* 清位 */
}
要点：volatile 保证每次访问真实执行；|=(1<<n) 置位、&=~(1<<n) 清位均不影响其它位；写前校验位号防越界。

