#include <stddef.h>

/* 拷贝 n 个字节；支持重叠：目标在源后方时从尾到头复制 */
void *my_memcpy(void *dst, const void *src, size_t n)
{
    char *d = dst;
    const char *s = src;
    if (d > s && d < s + n) {           /* 重叠且目标在后：从尾到头 */
        d += n;
        s += n;
        while (n--) *--d = *--s;
    } else {                            /* 其它情况：从头到尾 */
        while (n--) *d++ = *s++;
    }
    return dst;                         /* 返回目标首地址 */
}
/* 调用示例：my_memcpy(buf + 2, buf, 10); 用法与 memcpy 相同 */
要点：重叠安全；O(n) 时间、O(1) 空间；返回 dst 支持链式调用。

完整程序如下（含交换优化）：
#include <stdio.h>
#define N 10               /* 数组大小可自行修改 */

void bubble_sort(int num[], int n)
{
    int i, j, t;
    int swapped;           /* 优化：若某轮没有交换说明已有序，可提前结束 */
    for (i = 0; i < n - 1; i++) {              /* 控制比较轮数 */
        swapped = 0;
        for (j = 0; j < n - 1 - i; j++) {      /* 每轮比较次数递减（-i 因为末尾已排好） */
            if (num[j] > num[j + 1]) {         /* 大的往后冒 → 从小到大 */
                t = num[j + 1];
                num[j + 1] = num[j];
                num[j] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;                   /* 已完全有序 */
    }
}

int main(void)
{
    int a[N], n, i;
    printf("请输入需要排序的数的个数: \n");
    scanf("%d", &n);
    printf("请依次输入要排序的数: \n");
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    bubble_sort(a, n);
    printf("从小到大的排序为: \n");
    for (i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
要点：①两层循环——外层控制轮数（n-1 轮），内层控制每轮比较次数（n-1-i，因每轮结束末尾 i 个元素已就位）；②相邻比较、逆序则交换，使较大元素逐步冒到末尾；③时间复杂度 O(n²)（用 swapped 优化后最好情况 O(n)），空间 O(1)，稳定排序（只在严格大于时交换）；④若要从大到小只需把大于号改成小于号；⑤数据量大时应换用 qsort/快排。

