#include <vector>
#include <string>

/* 文件系统节点基类：统一接口多态；虚析构保证经基类指针删除安全 */
class FsNode {
public:
    virtual ~FsNode() {}
    virtual std::string name() const = 0;
};

class File : public FsNode {          /* 文件：叶子节点 */
    std::string m_name;
    unsigned long m_size;
public:
    std::string name() const override { return m_name; }
    void setName(const std::string &n) { m_name = n; }
};

class Directory : public FsNode {     /* 目录：容器，自关联包含子项 */
    std::string m_name;
    std::vector<FsNode *> m_children;
public:
    std::string name() const override { return m_name; }
    void add(FsNode *node) { m_children.push_back(node); }
};

class Partition {                     /* 分区：拥有一个根目录 */
public:
    Directory root;
};

class HardDisk {                      /* 硬盘：拥有多个分区 */
public:
    std::vector<Partition> parts;
};
要点：硬盘-分区-目录为组合关系；Directory 自关联包含子目录与文件；统一基类多态遍历。

核心结构（抽象交易类 + 注册表 + 服务器循环）如下：
#include <map>
#include <cstddef>

/* 抽象交易处理类：所有交易处理器的公共接口 */
class Transaction {
public:
    virtual ~Transaction() {}
    virtual int parse(const char *msg, int len) = 0;    /* 解析报文 */
    virtual int process(char *resp, int &rlen) = 0;     /* 处理并生成应答 */
    virtual int type() const = 0;                       /* 交易码 */
};

/* 交易注册表：交易码 -> 处理类对象 */
class TxRegistry {
    std::map<int, Transaction *> table;
public:
    void reg(Transaction *t) { table[t->type()] = t; }
    Transaction *find(int code) {
        auto it = table.find(code);
        return it == table.end() ? nullptr : it->second;   /* 未注册返回空 */
    }
};

/* 服务器主循环（伪代码）：
   socket recv -> 校验长度 -> 读交易码 code -> find(code)
   -> parse(msg,len) -> process(resp,rlen) -> socket send；失败回错误码 */
要点：多态分发 + 注册表解耦——新增交易只加子类并 reg；未注册交易码返回错误；解析前必须校验长度。

