#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* 改为二级指针：把 malloc 的地址写回调用者 */
void GetMemory(char * *p, unsigned int size)
{
    *p = (char *)malloc(size);
    if (*p == NULL) { /* 错误处理 */ }
}

int main(void)
{
    char *str = NULL;
    GetMemory(&str, 100);          /* 传 str 的地址，函数才能修改 str */
    if (str) {
