char *strcpy(char *strDest, const char *strSrc)
{
    char *p = strDest;                      /* 保存目标首地址用于返回 */
    while ((*p++ = *strSrc++) != '\0')      /* 逐字符拷贝，'\0' 也拷入并终止 */
        ;
    return strDest;
}
