配套类声明与四个成员函数实现（深拷贝、自赋值检查、释放旧内存）：
#include <cstring>

class String {
public:
    String(const char *str = nullptr);
    String(const String &other);
    ~String();
    String &operator=(const String &rhs);
private:
    char *m_data;
};

String::String(const char *str) {
    if (!str) {                        /* 空指针：分配 1 字节存 '\0' */
        m_data = new char[1];
        m_data[0] = '\0';
    } else {
        m_data = new char[strlen(str) + 1];
        strcpy(m_data, str);
    }
}
String::String(const String &other) {  /* 拷贝构造：深拷贝 */
    m_data = new char[strlen(other.m_data) + 1];
    strcpy(m_data, other.m_data);
}
String::~String() { delete [] m_data; } /* 析构：配对释放 */

String &String::operator=(const String &rhs) {
    if (this != &rhs) {                 /* 自赋值检查 */
        delete [] m_data;               /* 释放旧内存 */
        m_data = new char[strlen(rhs.m_data) + 1];
        strcpy(m_data, rhs.m_data);
    }
    return *this;                       /* 返回引用支持连续赋值 */
}
要点：深拷贝防双重释放；自赋值检查；先释放再分配；返回 *this。

架构设计要点（可照着画类图）：
① 状态模式：抽象状态 LifeState（接口 onEnter/name）；具体状态类——Energetic（精神饱满）、Normal（正常）、Tired（疲倦）、Danger（危险）、Dead（死亡），各自实现进入行为（UI 颜色、可行动性等），并按生命值阈值触发状态转移。
② 观察者模式：观察者接口 LifeObserver（onStateChanged）；Role 作为 Subject 维护观察者列表（attach/detach），状态切换时 notify 全体（UI、音效、成就等订阅方）。
顶层结构：Role（角色上下文：生命值 + 当前状态 + 观察者列表）→ setState 委托状态对象并广播通知；UI 模块实现 LifeObserver 更新显示。关键类骨架：
#include <vector>

/* 状态接口：每种生命状态实现自己的行为与转移条件 */
class LifeState {
public:
    virtual ~LifeState() {}
    virtual void onEnter(class Role *role) = 0;
    virtual const char *name() const = 0;
};

/* 观察者接口：UI/音效/成就等实现 */
class LifeObserver {
public:
    virtual ~LifeObserver() {}
    virtual void onStateChanged(class Role *role, const char *state) = 0;
};

/* 上下文：角色持有当前状态与观察者列表，切换状态时通知观察者 */
class Role {
    LifeState *m_state = nullptr;
    std::vector<LifeObserver *> m_obs;
public:
    void attach(LifeObserver *o) { m_obs.push_back(o); }
    void setState(LifeState *s) {
        m_state = s;
        if (m_state) {
            m_state->onEnter(this);
            for (auto o : m_obs) o->onStateChanged(this, m_state->name());
        }
    }
};
说明：状态类之间按生命值阈值转移（如低于下限进入 Danger）；UI 等通过实现 LifeObserver 订阅变化；两模式组合使状态逻辑与显示逻辑解耦。

完整程序（哈希标记 + 双指针原地去重，O(n)）：
#include <stdio.h>

/* 原地去除重复字符：每个字符只保留第一次出现，其余删除 */
void dedup(char *s)
{
    int seen[256] = {0};        /* 桶标记：字符是否已出现过 */
    char *w = s;                /* 写指针 */
    for (char *r = s; *r; r++) {/* 读指针 */
        unsigned char c = (unsigned char)*r;
        if (!seen[c]) {
            seen[c] = 1;
            *w++ = c;           /* 首次出现：写入并前移 */
        }
    }
    *w = '\0';                  /* 补上新的结尾 */
}

int main(void)
{
    char buf[10001];            /* 题目限长 ≤10000 */
    printf("请输入字符串: ");
    if (scanf("%10000s", buf) != 1) return 1;
    dedup(buf);
    printf("%s\n", buf);        /* 例: abcaadc -> abcd */
    return 0;
}
要点：seen[256] 标记 + 双指针原地重写；O(n) 时间、O(1) 额外空间（仅 256 桶）；结果保持首次出现的顺序。

完整程序（DWORD 秒数自 2000-01-01 0:0:0 起转日期时间字符串）：
#include <stdio.h>

/* 把自 2000-01-01 0:0:0 起的 DWORD 秒数转换为日期时间并打印 */
void sec2time(unsigned int sec)
{
    static const int mdays[] = {31,28,31,30,31,30,31,31,30,31,30,31};
    int year = 2000, month = 1, day, hour, min, sec2p;

    while (1) {                              /* 逐年扣，确定年份 */
        int ydays = (year % 4 == 0) ? 366 : 365;
        if (sec >= ydays * 86400u) { sec -= ydays * 86400u; year++; }
        else break;
    }
    while (1) {                              /* 逐月扣，确定月份 */
        int m = mdays[month - 1];
        if (month == 2 && year % 4 == 0) m = 29;   /* 闰年 2 月 29 天 */
        if (sec >= m * 86400u) { sec -= m * 86400u; month++; }
        else break;
    }
    day  = sec / 86400 + 1;  sec %= 86400;   /* 日期从 1 起算 */
    hour = sec / 3600;       sec %= 3600;
    min  = sec / 60;         sec2p = sec % 60;
    printf("%d年%02d月%02d日 %02d时%02d分%02d秒\n",
           year, month, day, hour, min, sec2p);
}

int main(void)
{
    unsigned int sec;
    printf("请输入 DWORD 秒数（自 2000-01-01 0:0:0 起）: ");
    if (scanf("%u", &sec) != 1) return 1;
    sec2time(sec);
    return 0;
}
要点：逐年→逐月→逐级除；2 月闰年处理；日期从 1 起算要 +1。

完整程序如下（数字反转法，不使用字符串库函数）：
#include <stdio.h>

/* 判断是否为回文数（对称数）：反转数字与原数比较；负数不是回文数 */
int is_palindrome(long x)
{
    long orig, rev = 0;
    if (x < 0) return 0;               /* 负数（含负号）不是回文数 */
    orig = x;
    while (x) {
        rev = rev * 10 + x % 10;       /* 逐位反转 */
        x /= 10;
    }
    return rev == orig;                /* 反转后相等即为回文 */
}

int main(void)
{
    long n;
    printf("请输入一个整数: ");
    if (scanf("%ld", &n) != 1) return 1;
    printf("%s\n", is_palindrome(n) ? "是对称数" : "不是对称数");
    return 0;
}
示例：3、121、12321、45254 返回「是对称数」；-121、123 返回「不是对称数」。要点：O(位数) 时间、O(1) 空间；负数单独约定。

完整程序如下（每两字符拼一字节，高位在前）：
#include <stdio.h>

/* 单字符转数值：'0'~'9'/'a'~'f'/'A'~'F' -> 0~15；非法返回 -1 */
int hex_val(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

/* 每两个字符拼成一个字节（高半字节在前）；返回转换出的字节数 */
int str_to_hex(const char *s, unsigned char *out, int max)
{
    int n = 0;
    while (s[0] && s[1] && n < max) {
        int hi = hex_val(s[0]), lo = hex_val(s[1]);
        if (hi < 0 || lo < 0) break;        /* 遇到非法字符：停止 */
        out[n++] = (unsigned char)((hi << 4) | lo);
        s += 2;
    }
    return n;
}

int main(void)
{
    char buf[256];
    unsigned char out[128];
    int n, i;
    printf("请输入 0-9/a-f/A-F 组成的字符串: ");
    if (scanf("%255s", buf) != 1) return 1;
    n = str_to_hex(buf, out, (int)sizeof(out));
    printf("共导出 %d 个字节: ", n);
    for (i = 0; i < n; i++) printf("0x%02X ", out[i]);
    printf("\n");
    return 0;
}
示例："1234" -> 0x12, 0x34。要点：两两成组、高半字节在前；非法字符与奇数尾字符按停止处理。

