#include <stdio.h>
#include <stdint.h>

/* 16 位无符号数高低字节交换：0x1234 -> 0x3412 */
uint16_t swap_bytes(uint16_t x)
{
    return (uint16_t)((x >> 8) | (x << 8));
}

int main(void)
{
    uint16_t v = 0x1234;
    printf("0x%04X -> 0x%04X\n", v, swap_bytes(v));   /* 0x1234 -> 0x3412 */
    return 0;
}
要点：(x>>8) 移高字节到低位、(x<<8) 移低字节到高位，或运算合并后截断；O(1) 时间、O(1) 空间；也可用联合体或 __builtin_bswap16 实现。

