完整程序如下：
#include <stdio.h>
#include <stdint.h>

/* 16 位无符号数位反转（位序颠倒）：0x1234 -> 0x2C48 */
uint16_t reverse_bits(uint16_t x)
{
    uint16_t r = 0;
    for (int i = 0; i < 16; i++) {
        r = (uint16_t)((r << 1) | (x & 1));   /* 取 x 最低位拼到 r 末尾 */
        x >>= 1;                              /* x 右移，处理下一位 */
    }
    return r;
}

int main(void)
{
    uint16_t v = 0x1234;
    printf("0x%04X -> 0x%04X\n", v, reverse_bits(v));   /* 0x1234 -> 0x2C48 */
    return 0;
}
要点：16 次「取最低位→r 左移并入→x 右移」；O(16) 即 O(1)；大数据量可用 256 字节倒序查表加速。

完整程序如下：
#include <stdio.h>
#include <stdint.h>

/* 8 位奇偶校验：1 的个数为奇数返回 1，偶数返回 0 */
int parity8(uint8_t x)
{
    int cnt = 0;
    while (x) {
        cnt += x & 1;        /* 统计当前最低位 */
        x >>= 1;             /* 右移继续 */
    }
    return cnt & 1;          /* 个数对 2 取余：奇数为 1、偶数为 0 */
}

int main(void)
{
    printf("0x0F -> %d\n", parity8(0x0F));   /* 4 个 1：偶数，返回 0 */
    printf("0x07 -> %d\n", parity8(0x07));   /* 3 个 1：奇数，返回 1 */
    return 0;
}
要点：逐位统计后取 mod 2；O(8) 即 O(1)；可用异或折叠或 __builtin_parity 优化。

