/* 单链表节点定义 */
struct ListNode {
    int val;
    ListNode *next;
};

/* 删除所有值为 val 的节点，返回新头（哨兵节点法） */
ListNode* removeElements(ListNode* head, int val)
{
    ListNode dummy{0, head};        /* 哨兵：dummy.next = head */
    ListNode *p = &dummy;
    while (p->next) {
        if (p->next->val == val) {
            ListNode *del = p->next;    /* 摘链并释放 */
            p->next = del->next;
            delete del;                 /* 删除时 p 不前移 */
        } else {
            p = p->next;                /* 非目标：前移 */
        }
    }
    return dummy.next;              /* 新头 */
}
/* 调用示例：head = removeElements(head, 6); */
要点：哨兵统一「删头/删中间」；删除时不前移 p、可连续删；O(n)/O(1)。

