#include <stdio.h>
#include <string.h>

/* 原地逆序字符串：双指针两端向中间交换，O(1) 额外空间 */
void str_reverse(char *s)
{
    char *e = s + strlen(s) - 1;      /* 指向最后一个字符 */
    while (s < e) {                   /* 两端向中间靠拢 */
        char t = *s;
        *s++ = *e;
        *e-- = t;
    }
}

int main(void)
{
    char t[] = "hello";
    str_reverse(t);
    puts(t);                          /* olleh */
    return 0;
}
要点：双指针原地交换 O(n)/O(1)；测试必须用可修改的字符数组；空串/单字符天然安全。

完整函数（含调用示例）如下：
/* 最长无重复字符子串的长度（滑动窗口） */
int length_of_longest_substring(const char *s)
{
    int last[256], start = 0, best = 0;
    int i;

    for (i = 0; i < 256; i++)
        last[i] = -1;                 /* -1：该字符尚未出现过 */

    for (i = 0; s[i]; i++) {
        unsigned char c = s[i];       /* 防有符号 char 产生负下标 */
        if (last[c] >= start)         /* 上次出现在窗口内：发现重复 */
            start = last[c] + 1;      /* 窗口左端右移、跳过旧位置 */
        last[c] = i;
        if (i - start + 1 > best)     /* 刷新最优长度 */
            best = i - start + 1;
    }
    return best;
}
/* 调用示例：length_of_longest_substring("abcabcbb") 返回 3（子串 "abc"） */
要点：窗口 [start,i] 内恒无重复；last[256] 记忆字符最近位置；O(n) 时间、O(1) 空间。

