            while (GPIO_ReadInputDataBit(KEY_GPIO_PORT, KEY_PIN) == 0)
                ;                                              /* 等待按键释放，防重复触发 */
        }
    }
}
/* 调用方式：主循环 while(1) 中周期调用 key_scan(); */
