#define BIT5 (0x1<<5)
static int a;

/* 置位：把 a 的 bit5 置 1，其余位不变 */
void set_bit(void)
{
    a |= BIT5;          /* 0|1=1 置位；其余位 x|0=x 保持不变 */
}

/* 清零：把 a 的 bit5 清 0，其余位不变 */
void clear_bit(void)
{
    a &= ~BIT5;         /* ~BIT5 为除 bit5 外全 1 的掩码；目标位 x&0=0 清 0，其余位 x&1=x 不变 */
}
要点：置位用或 1、清零用与 0（掩码取反）；^= 是翻转而非清零；通用写法 a |= (1u<<n); a &= ~(1u<<n);。

软件模拟 SPI 的完整实现如下（引脚操作以 STM32 标准库为例，可按平台替换）：
/* 连接：MCU P10~P13 → SPI_Flash 的 /CS、MOSI(DI)、MISO(DO)、CLK */
#define CS_LOW()      GPIO_ResetBits(GPIOA, GPIO_Pin_10)   /* /CS 拉低：选中器件 */
#define CS_HIGH()     GPIO_SetBits(GPIOA, GPIO_Pin_10)
#define CLK_LOW()     GPIO_ResetBits(GPIOA, GPIO_Pin_13)   /* CLK 时钟线 */
#define CLK_HIGH()    GPIO_SetBits(GPIOA, GPIO_Pin_13)
#define MOSI_WRITE(x) do { if (x) GPIO_SetBits(GPIOA, GPIO_Pin_11); \
                           else   GPIO_ResetBits(GPIOA, GPIO_Pin_11); } while (0)
#define MISO_READ()   GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_12)   /* 返回 0/1 */

static void spi_delay(void) { /* 短延时：决定 SCK 频率（按 Flash 允许上限调整） */ }

/* 发送并接收 1 字节：MSB first、上升沿采样（Mode0：CPOL=0，CPHA=0） */
static unsigned char spi_rw(unsigned char dat)
{
    unsigned char i, rd = 0;
    for (i = 0; i < 8; i++) {
        CLK_LOW();                            /* 时钟拉低：准备数据 */
        MOSI_WRITE((dat & 0x80) ? 1 : 0);     /* 先发最高位（MSB first） */
        dat <<= 1;
        spi_delay();
        CLK_HIGH();                           /* 上升沿：从机采样 MOSI、主机读 MISO */
        rd = (rd << 1) | MISO_READ();         /* 读入 1 位（MSB first） */
        spi_delay();
    }
    CLK_LOW();
    return rd;
}

/* 读 Flash：/CS 拉低 → 03h → 24 位地址 → 连续读 len 字节 → /CS 拉高 */
void spi_flash_read(unsigned long addr, unsigned char *buf, unsigned int len)
{
    unsigned int i;
    CS_LOW();                                   /* 片选拉低，整帧保持有效 */
    spi_rw(0x03);                               /* 读数据指令 03h */
    spi_rw((unsigned char)(addr >> 16));        /* 地址高字节（24 位，高位先发） */
    spi_rw((unsigned char)(addr >> 8));         /* 地址中字节 */
    spi_rw((unsigned char)(addr));              /* 地址低字节 */
    for (i = 0; i < len; i++)
        buf[i] = spi_rw(0xFF);                  /* 主机发 dummy，移位读出数据 */
    CS_HIGH();                                  /* 片选拉高，结束操作 */
}
要点：/CS 全程低电平；顺序 = 03h → 24 位地址 → 连续读；MSB first、Mode0 上升沿采样；时钟频率不超 Flash 上限。

常用数字滤波算法及完整实现如下：
#include <stdlib.h>

/* ① 限幅滤波：新值与上次值差超过 A_MAX 视为脉冲，输出上次值 */
#define A_MAX 20
int limit_filter(int new_val, int old_val)
{
    return (abs(new_val - old_val) > A_MAX) ? old_val : new_val;
}

/* ② 中值滤波：连续采 N（奇数）次，排序后取中间值（抗脉冲） */
#define N_MID 5
int median_filter(int (*get_adc)(void))
{
    int buf[N_MID], i, j, t;
    for (i = 0; i < N_MID; i++)
        buf[i] = get_adc();
    for (i = 0; i < N_MID - 1; i++)                 /* 冒泡排序 */
        for (j = 0; j < N_MID - 1 - i; j++)
            if (buf[j] > buf[j + 1]) {
                t = buf[j]; buf[j] = buf[j + 1]; buf[j + 1] = t;
            }
    return buf[N_MID / 2];                          /* 中间值 */
}

/* ③ 递推平均滤波：环形缓冲滑动窗口，输出最近 N 个点的均值 */
#define N_AVG 8
int avg_filter(int new_val)
{
    static int  buf[N_AVG];
    static int  idx = 0;
    static long sum = 0;
    sum -= buf[idx];                    /* 旧值出窗 */
    buf[idx] = new_val;                 /* 新值入窗 */
    sum += new_val;
    idx = (idx + 1) % N_AVG;
    return (int)(sum / N_AVG);
}

/* ④ 一阶低通（惯性）滤波：Y(n)=a*X(n)+(1-a)*Y(n-1)，a 越小越平滑 */
#define ALPHA_NUM 1                 /* a = ALPHA_NUM/ALPHA_DEN = 1/8 */
#define ALPHA_DEN 8
int lpf_filter(int new_val)
{
    static int last = 0;
    last = (ALPHA_NUM * new_val + (ALPHA_DEN - ALPHA_NUM) * last) / ALPHA_DEN;
    return last;
}
要点：脉冲干扰用限幅/中值/去极值；随机噪声用递推平均；缓变量求实时用一阶低通；均以「平滑度 vs 响应速度」折中选型。

简化版完整实现如下（底层输出 uart_putc 换成任意平台/串口均可）：
#include <stdarg.h>

static void uart_putc(char c) { /* 把 c 写入 UART 发送寄存器并等待发送完成（按平台实现） */ }

static void out_str(const char *s) { while (*s) uart_putc(*s++); }

static void out_num(unsigned long v, int base, int upper, int width, char pad)
{
    char tmp[32]; int n = 0;
    const char *dig = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    if (v == 0) tmp[n++] = '0';
    while (v) { tmp[n++] = dig[v % base]; v /= base; }   /* 除基取余：得到逆序字符 */
    while (n < width) tmp[n++] = pad;                    /* 左补零/空格 */
    while (n--) uart_putc(tmp[n]);                       /* 逆序输出 */
}

/* 支持 %d/%i/%u/%x/%X/%p/%c/%s/%% 与宽度、0 填充 */
int my_printf(const char *fmt, ...)
{
    va_list ap;
    int cnt = 0;
    va_start(ap, fmt);
    while (*fmt) {
        if (*fmt != '%') { uart_putc(*fmt++); cnt++; continue; }
        fmt++;                                   /* 跳过 '%' */
        int width = 0;
        char pad = ' ';
        if (*fmt == '0') { pad = '0'; fmt++; }
        while (*fmt >= '0' && *fmt <= '9') width = width * 10 + (*fmt++ - '0');
        switch (*fmt) {
        case 'd': case 'i': {
            int v = va_arg(ap, int);
            if (v < 0) { uart_putc('-'); cnt++; out_num((unsigned long)(-v), 10, 0, width, pad); }
            else       out_num((unsigned long)v, 10, 0, width, pad);
            break; }
        case 'u': out_num(va_arg(ap, unsigned int), 10, 0, width, pad); break;
        case 'x': out_num(va_arg(ap, unsigned int), 16, 0, width, pad); break;
        case 'X': out_num(va_arg(ap, unsigned int), 16, 1, width, pad); break;
        case 'p': out_str("0x"); out_num((unsigned long)va_arg(ap, void *), 16, 0, 8, '0'); break;
        case 'c': uart_putc((char)va_arg(ap, int)); break;
        case 's': { char *s = va_arg(ap, char *); if (!s) s = "(null)"; out_str(s); break; }
        case '%': uart_putc('%'); break;
        default:  uart_putc('%'); uart_putc(*fmt); break;
        }
        fmt++;
    }
    va_end(ap);
    return cnt;
}
要点：va_list 变参 + 格式状态机 + 除基取余逆序数字；工程可先用 vsnprintf 格式化再输出；%d 等类型必须与实参匹配。

完整实现（含调用示例）如下：
#include <stdio.h>
#include <stdlib.h>

typedef struct dnode {
    int             data;
    struct dnode   *prev;
    struct dnode   *next;
} dnode_t;

typedef struct {
    dnode_t *head;
    dnode_t *tail;
    int      size;
} dlist_t;

/* 初始化空链表 */
void dlist_init(dlist_t *l) { l->head = l->tail = NULL; l->size = 0; }

/* 尾插：返回新节点（失败返回 NULL） */
dnode_t *dlist_push_back(dlist_t *l, int v)
{
    dnode_t *n = (dnode_t *)malloc(sizeof(dnode_t));
    if (!n) return NULL;
    n->data = v;
    n->next = NULL;
    n->prev = l->tail;
    if (l->tail) l->tail->next = n;     /* 原尾节点指向新节点 */
    else         l->head = n;           /* 空链表：头也要指新节点 */
    l->tail = n;
    l->size++;
    return n;
}

/* 头插 */
dnode_t *dlist_push_front(dlist_t *l, int v)
{
    dnode_t *n = (dnode_t *)malloc(sizeof(dnode_t));
    if (!n) return NULL;
    n->data = v;
    n->prev = NULL;
    n->next = l->head;
    if (l->head) l->head->prev = n;
    else         l->tail = n;           /* 空链表：尾也要指新节点 */
    l->head = n;
    l->size++;
    return n;
}

/* 按值查找（返回首个匹配节点，未找到返回 NULL） */
dnode_t *dlist_find(dlist_t *l, int v)
{
    dnode_t *p;
    for (p = l->head; p; p = p->next)
        if (p->data == v) return p;
    return NULL;
}

/* 按值删除：处理 头/尾/中间 三种情况；找到删除返回 0，未找到返回 -1 */
int dlist_erase(dlist_t *l, int v)
{
    dnode_t *p = dlist_find(l, v);
    if (!p) return -1;
    if (p->prev) p->prev->next = p->next; else l->head = p->next;  /* 删头 */
    if (p->next) p->next->prev = p->prev; else l->tail = p->prev;  /* 删尾 */
    free(p);
    l->size--;
    return 0;
}

/* 正向 / 反向遍历 */
void dlist_print(dlist_t *l)
{
    dnode_t *p;
    for (p = l->head; p; p = p->next) printf("%d ", p->data);
    printf("\n");
    for (p = l->tail; p; p = p->prev) printf("%d ", p->data);
    printf("\n");
}

/* 释放全部节点 */
void dlist_free(dlist_t *l)
{
    dnode_t *p = l->head, *nx;
    while (p) { nx = p->next; free(p); p = nx; }   /* 先存 next 再 free */
    dlist_init(l);
}

/* 调用示例 */
int main(void)
{
    dlist_t l;
    dlist_init(&l);
    dlist_push_back(&l, 1);
    dlist_push_back(&l, 2);
    dlist_push_front(&l, 0);      /* 0 1 2 */
    dlist_print(&l);              /* 正向 0 1 2；反向 2 1 0 */
    dlist_erase(&l, 1);           /* 0 2 */
    dlist_free(&l);
    return 0;
}
要点：节点含 prev/next，可双向遍历、已知节点插入/删除 O(1)；头尾边界单独处理；free 前先存 next。

四种实现如下（考试推荐第 1 种）：
/* ① 指针版：C 标准做法（传地址才能交换实参） */
void swap(int *a, int *b)
{
    int t = *a; *a = *b; *b = t;        /* 经指针访问实参变量 */
}

/* ② 宏版：可交换任意类型（GCC typeof 扩展；do-while(0) 保证单语句语义） */
#define SWAP(a, b) do { \
        typeof(a) _t = (a); (a) = (b); (b) = _t; \
    } while (0)

/* ③ 通用字节版：交换任意类型的内存块（size 为字节数） */
void swap_any(void *a, void *b, unsigned int size)
{
    unsigned char *pa = (unsigned char *)a, *pb = (unsigned char *)b, t;
    while (size--) { t = *pa; *pa++ = *pb; *pb++ = t; }
}

/* ④ 异或版：不用临时变量（仅整型；同址会清零，必须先判） */
void swap_xor(int *a, int *b)
{
    if (a == b) return;                 /* 防同一变量：否则被清零 */
    *a ^= *b; *b ^= *a; *a ^= *b;
}
要点：值传递必须传指针（C++ 可传引用，如 void swap(int &a, int &b)）；异或版仅整型且须判同址；宏版注意副作用与 do-while(0)。

