/* ① 指针版（推荐）：指针差即为长度 */
unsigned int strlen_p(const char *s)
{
    const char *p = s;
    while (*p) p++;                 /* 走到结尾 '\0' */
    return (unsigned int)(p - s);   /* 不含 '\0' */
}

/* ② 计数版 */
unsigned int strlen_c(const char *s)
{
    unsigned int n = 0;
    while (s[n] != '\0') n++;
    return n;
}

/* ③ 递归版（仅作理解，实际不用：深串爆栈） */
unsigned int strlen_r(const char *s)
{
    return *s ? 1 + strlen_r(s + 1) : 0;
}
/* 调用示例：strlen_p("abc") 返回 3；注意 char s[]="abc" 时 sizeof(s)==4 */
