}

int main(void)
{
    char dest[50] = {0};
    char src[50]  = "hello";

    printf("请输入字符串: ");
    scanf("%s", src);                   /* 工程上应限制宽度防溢出，如 %49s */
    my_strcpy(dest, src);
    printf("当前获取的字符串为 %s\n", dest);
