完整程序如下：
#include <stdio.h>
#include <string.h>

/* 自实现字符串拼接：从 dest 末尾追加 src，返回 dest */
char *my_strcat(char *dest, const char *src)
{
    int len1 = strlen(dest);             /* 目标串已有长度：从 '\0' 处开始追加 */
    int len2 = strlen(src);
    int i;
    for (i = len1; i < len1 + len2; i++) /* 覆盖原 '\0'，逐字符追加 */
        dest[i] = src[i - len1];
    dest[i] = '\0';                      /* 重新封口 */
    return dest;
}

int main(void)
{
    char dest[50] = "hello";             /* 必须预留足够空间 */
    char src[50]  = "World";
    my_strcat(dest, src);
    printf("当前获取的字符串为 %s\n", dest);   /* helloWorld */
    return 0;
}
要点：从 dest 原 '\0' 处开始写并重新补 '\0'；返回 dest；空间不足会溢出，调用前须核对容量。

完整程序如下（下标版为主、指针版等价）：
#include <stdio.h>

/* 下标版：相等返回 0，s1>s2 返回正数，s1<s2 返回负数 */
int my_strcmp(const char *s1, const char *s2)
{
    int i = 0;
    while (s1[i] == s2[i]) {              /* 字符相同则继续 */
        if (s1[i] == '\0') return 0;      /* 同时到结尾：完全相等 */
        i++;
    }
    return (unsigned char)s1[i] - (unsigned char)s2[i];   /* 首个不同字符定胜负 */
}

/* 指针版（等价、更简洁） */
int my_strcmp_p(const char *s1, const char *s2)
{
    while (*s1 && (*s1 == *s2)) { s1++; s2++; }
    return (unsigned char)*s1 - (unsigned char)*s2;
}

int main(void)
{
    char s1[50] = "hello";
    char s2[50] = "helloworld";
    int ret = my_strcmp(s1, s2);
    if (ret == 0) printf("s1 == s2\n");
    else          printf("s1 != s2\n");   /* 本例走这里 */
    return 0;
}
要点：逐字符比较、首个不同处返回差值（0/正/负）；按 unsigned char 比较；返回值语义别写错。

以插入排序为例的完整函数（含调用示例）如下：
/* 插入排序：原地、稳定、最好 O(n)、平均/最坏 O(n^2) */
void insertion_sort(int a[], int n)
{
    int i, j, key;
    for (i = 1; i < n; i++) {
        key = a[i];                    /* 待插入元素 */
        j = i - 1;
        while (j >= 0 && a[j] > key) { /* 比 key 大的元素整体后移 */
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;                /* 插入到正确位置 */
    }
}
/* 调用示例：int a[] = {5,2,4,1,3}; insertion_sort(a, 5); 得 1,2,3,4,5 */
要点：已排序区+未排序区逐轮扩大；O(n^2) 最坏 / O(n) 最好、O(1) 空间、稳定；小规模与近乎有序时效率高。

