#include <stdio.h>

/* 递归倒序输出整数：12345 → 54321 */
void print_reverse(int n)
{
    if (n < 0) {                 /* 负数：先输出负号再按正数处理 */
        putchar('-');
        n = -n;                  /* 注：INT_MIN 取负会溢出，工程上可先转 long long */
    }
    printf("%d", n % 10);        /* 先输出最低位（决定倒序） */
    if (n >= 10)                 /* 还有高位：递归处理 */
        print_reverse(n / 10);
}

int main(void)
{
    int x;
    printf("请输入一个整数: ");
    if (scanf("%d", &x) != 1) return 1;
    print_reverse(x);
    putchar('\n');
    return 0;
}
要点：先输出 n%10 再递归 n/10 = 倒序；顺序调换则成正序；注意负号与 INT_MIN 边界。

完整程序如下（DP 求最长公共子串，并指出题面示例的笔误）：
#include <stdio.h>
#include <string.h>

/* 求最长公共子串：返回长度，并带出它在 s1 中的起始下标 */
int lcs_substr(const char *s1, const char *s2, int *start1)
{
    int m = (int)strlen(s1), n = (int)strlen(s2);
    int dp[300][300] = {0};        /* dp[i][j]：以 s1[i-1]、s2[j-1] 结尾的公共子串长度 */
    int i, j, best = 0, end1 = 0;

    for (i = 1; i <= m; i++)
        for (j = 1; j <= n; j++) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > best) { best = dp[i][j]; end1 = i; }  /* 记录最优 */
            } else {
                dp[i][j] = 0;      /* 子串要求连续：不等即断开 */
            }
        }
    if (start1) *start1 = end1 - best;
    return best;
}

int main(void)
{
    const char *a = "adbccadebbca", *b = "edabccadece";
    int start, len = lcs_substr(a, b, &start);
    printf("最长公共子串：%.*s（长度 %d，位于 a[%d]）\n", len, a + start, len, start);
    return 0;
}
要点：dp 相同 +1、不同清零（连续子串）；O(m×n) 时间；本题实测最长公共子串是 "bccade"（长度 6），题面示例 "ccade" 为笔误。

四个函数的完整实现如下：
#include <stddef.h>

/* strlen：到第一个 '\0' 为止的长度（不含 '\0'） */
size_t my_strlen(const char *s)
{
    size_t n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

/* strcpy：把 src（含 '\0'）复制到 dst，返回 dst */
char *my_strcpy(char *dst, const char *src)
{
    char *d = dst;
    while ((*d++ = *src++) != '\0')     /* 赋值表达式判结尾，'\0' 一并复制 */
        ;
    return dst;
}

/* strcat：先找到 dst 末尾，再接着复制 src（含 '\0'），返回 dst */
char *my_strcat(char *dst, const char *src)
{
    char *d = dst;
    while (*d != '\0')                  /* 走到 dst 结尾 */
        d++;
    while ((*d++ = *src++) != '\0')     /* 追加 src */
        ;
    return dst;
}

/* strcmp：相等返回 0，s1>s2 返回正，s1<s2 返回负（按 unsigned char 比较） */
int my_strcmp(const char *s1, const char *s2)
{
    while (*s1 != '\0' && *s1 == *s2) {
        s1++;
        s2++;
    }
    return (int)(unsigned char)*s1 - (int)(unsigned char)*s2;
}
/* 调用示例：char b[32]; my_strcpy(b, "ab"); my_strcat(b, "cd"); my_strcmp(b, "abcd"); */
要点：strcpy/strcat 返回 dst 支持链式；strcmp 返回 0/正/负并转 unsigned char；四者均无长度检查，工程需防溢出。

核心代码（快慢指针）如下，含进阶的找入环点：
#include <stddef.h>

typedef struct Node { int data; struct Node *next; } Node;

/* 判环：有环返回 1，无环返回 0；O(n) 时间、O(1) 空间、只读链表 */
int has_loop(const Node *head)
{
    const Node *slow = head, *fast = head;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;          /* 慢指针每次 1 步 */
        fast = fast->next->next;    /* 快指针每次 2 步 */
        if (slow == fast)           /* 相遇：有环 */
            return 1;
    }
    return 0;                       /* 快指针到尾：无环 */
}

/* 进阶：找入环点（无环返回 NULL） */
const Node *loop_entry(const Node *head)
{
    const Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {                 /* 相遇后一指针回起点 */
            slow = head;
            while (slow != fast) {          /* 同速前进，再遇即入环点 */
                slow = slow->next;
                fast = fast->next;
            }
            return slow;
        }
    }
    return NULL;
}
要点：快慢指针相遇 ⟺ 有环；O(n)/O(1) 满足只读、无额外数组的限制；入环点 = 相遇后一指针回起点、同速再遇。

