#include <stdio.h>
#include <stdint.h>

int main(void)
{
    /* 方法一：看整型的表示范围（经典判据：16 位 int 上限 0xFFFF） */
    unsigned int umax = ~0u;
    printf("整型宽度：%s\n", (umax > 0xFFFFu) ? ">=32 位" : "16 位");

    /* 方法二：看指针宽度（地址宽度＝字长）：全 1 指针即指针类型可表示的最大地址 */
    void *p = (void *)-1;
    uintptr_t addr = (uintptr_t)p;
    printf("指针宽度：%s\n", (addr > 0xFFFF) ? ">=32 位" : "16 位");

    /* 方法三：不用 sizeof，用指针差值求类型大小 */
    int arr[2];
    long nbytes = (long)((char *)&arr[1] - (char *)&arr[0]);   /* = sizeof(int) */
    printf("int 占 %ld 字节\n", nbytes);

    return 0;
}
要点：指针宽度即字长（最名正言顺）；指针转整数用 uintptr_t；指针差值可代替 sizeof 求类型大小。

