#include <stdio.h>

/* 打印倒三角形：底边 n 个 '*'，每行减 2、居中（n=7 末行 1 个；n=8 末行 2 个） */
int main(void)
{
    int n, i, j;

    printf("请输入底边长 n: ");
    if (scanf("%d", &n) != 1 || n <= 0)
        return 1;                            /* 输入校验 */

    for (i = n; i >= 1; i -= 2) {            /* 每行星号数：n, n-2, n-4 ... */
        for (j = 0; j < (n - i) / 2; j++)    /* 前导空格：实现居中 */
            putchar(' ');
        for (j = 0; j < i; j++)              /* 本行星号 */
            putchar('*');
        putchar('\n');
    }
    return 0;
}
运行效果：n=7 时从上到下每行依次打印 7、5、3、1 个星号 '*'（各行依次缩进 0、1、2、3 个空格、居中）；n=8 时每行依次打印 8、6、4、2 个星号、依次缩进 0、1、2、3 个空格（末行为 2 个星号）。
要点：星号数每行减 2、前导 (n-i)/2 个空格居中；偶数 n 末行为 2 个星号；双层循环 O(n^2)。

四种类型的 if 语句如下：
/* ① int 与零比较：直接与 0 比较 */
if (n == 0)  { /* n 等于零 */ }
if (n != 0)  { /* n 不等于零 */ }

/* ② bool 与零比较：直接判断本身，不写成 == true / == 1 */
if (flag)    { /* 真 */ }
if (!flag)   { /* 假 */ }
/* C99 起需 #include <stdbool.h>；C++ 原生支持 bool */

/* ③ float/double 与零比较：不能直接用 ==，应使用容差 */
#include <math.h>
#define EPS 1e-6                        /* 容差按数据量级选取（也可用 FLT_EPSILON） */
if (fabs(f) <= EPS) { /* 视为等于零 */ }
if (fabs(f) >  EPS) { /* 视为不等于零 */ }

/* ④ 指针与零比较：用 NULL（C++ 推荐 nullptr），不写裸 0 */
if (p == NULL) { /* 空指针 */ }
if (p != NULL) { /* 非空指针 */ }
要点：int 直比 0；bool 直接判断；浮点用容差 fabs(f)<=EPS；指针判 NULL。浮点若直接写 f==0.0，因二进制舍入常常不成立。

