完整函数如下（基础版 + 查表高效版）：
#include <stddef.h>

/* 基础版：掩码交换三步法（固定步骤、无需查表） */
unsigned char reverse_bits(unsigned char b)
{
    b = (unsigned char)(((b & 0x55u) << 1) | ((b & 0xAAu) >> 1));  /* 相邻 1 位交换 */
    b = (unsigned char)(((b & 0x33u) << 2) | ((b & 0xCCu) >> 2));  /* 相邻 2 位交换 */
    b = (unsigned char)((b << 4) | (b >> 4));                      /* 高 4 位与低 4 位交换 */
    return b;
}

/* 高效版：256 项查表 + 8 字节成组（适合频繁处理大数据量） */
static unsigned char g_rev8[256];

/* 启动时构建一次反转表 */
static void build_rev_table(void)
{
    int i;
    for (i = 0; i < 256; i++)
        g_rev8[i] = reverse_bits((unsigned char)i);
}

/* 处理整个缓冲区：每字节一次查表 + 一次写 */
void reverse_buffer(unsigned char *buf, size_t len)
{
    size_t i = 0;
    for (; i + 8 <= len; i += 8) {          /* 8 字节一组：减少循环开销 */
        buf[i+0] = g_rev8[buf[i+0]];
        buf[i+1] = g_rev8[buf[i+1]];
        buf[i+2] = g_rev8[buf[i+2]];
        buf[i+3] = g_rev8[buf[i+3]];
        buf[i+4] = g_rev8[buf[i+4]];
        buf[i+5] = g_rev8[buf[i+5]];
        buf[i+6] = g_rev8[buf[i+6]];
        buf[i+7] = g_rev8[buf[i+7]];
    }
    for (; i < len; i++)                    /* 收尾余数字节 */
        buf[i] = g_rev8[buf[i]];
}
/* 调用示例：先 build_rev_table() 一次；再 reverse_buffer(data, 1024*1024); */
要点：掩码三步法正确性（0x01 变 0x80、0xF0 变 0x0F）；频繁处理用查表 + 8 字节成组；表初始化一次；整体 O(n)。

