完整函数与测试如下（原型按题意定义：`void bytes_to_hex(const unsigned char *data, int len, char *out);`）：
#include <stdio.h>

/* 字节数组 → 十六进制字符串（大写）；out 至少 2*len+1 字节 */
void bytes_to_hex(const unsigned char *data, int len, char *out)
{
    const char *digits = "0123456789ABCDEF";
    int i;

    for (i = 0; i < len; i++) {
        out[2 * i]     = digits[data[i] >> 4];      /* 高 4 位 */
        out[2 * i + 1] = digits[data[i] & 0x0F];    /* 低 4 位 */
    }
    out[2 * len] = '\0';                            /* 按长度处理，0x00 也转 "00" */
}

int main(void)
{
    unsigned char buf[] = {0x12, 0xAB, 0x00, 0xFF};
    char hex[2 * sizeof(buf) + 1];
    int i;

    bytes_to_hex(buf, (int)sizeof(buf), hex);
    printf("hex = %s\n", hex);                      /* hex = 12AB00FF */
    for (i = 0; i < (int)sizeof(buf); i++)          /* 与 printf 对照校验 */
        printf("%02X", buf[i]);
    printf("\n");
    return 0;
}
输出：`hex = 12AB00FF` 与对照行 `12AB00FF`。

