        }
    }
    printf("字母：%d，数字：%d，空格：%d，其他：%d\n",
           letters, digits, spaces, others);
    return 0;
}
运行示例：输入 `abc 12 !#` → 输出「字母：3，数字：2，空格：2，其他：2」（已 gcc 实测验证）。

模块化实现（接口里带上缓冲区容量以便做边界检查），完整可编译：
#include <stdio.h>
#include <string.h>

/* 把 src 插入 dst 的 pos 位置（原地修改）。
   dst : 目标缓冲区（必为可写数组/堆内存，不能是字符串字面量）
   cap : dst 的总容量（含结尾符），用于越界检查
   pos : 插入位置，取值 0 ~ strlen(dst)
   返回 : 0 成功；-1 参数为空；-2 pos 越界；-3 容量不足 */
int str_insert(char *dst, size_t cap, const char *src, size_t pos)
{
    size_t dst_len, src_len, i;

    if (dst == NULL || src == NULL) return -1;      /* 空指针检查 */
    dst_len = strlen(dst);
    src_len = strlen(src);
    if (pos > dst_len) return -2;                   /* 插入位置越界 */
    if (dst_len + src_len + 1 > cap) return -3;     /* 空间不足，直接拒绝 */

    /* 1) 腾位置：把 pos 及其后内容（含结尾符）整体后移 src_len 字节。
       必须从后往前搬，否则会覆盖尚未搬移的数据；memmove 天然处理重叠。 */
    memmove(dst + pos + src_len, dst + pos, dst_len - pos + 1);

    /* 2) 写入待插入内容（只拷 src_len 字节，结尾符已由第 1 步就位） */
    memcpy(dst + pos, src, src_len);

    return 0;
}

int main(void)
{
    char buf[64] = "hello world";                   /* 中间插入 */
    printf("ret=%d [%s]\n", str_insert(buf, sizeof buf, "big ", 6), buf);

    strcpy(buf, "world");                           /* 头部插入 */
    printf("ret=%d [%s]\n", str_insert(buf, sizeof buf, "hello ", 0), buf);

    strcpy(buf, "abc");                             /* 尾部追加 */
    printf("ret=%d [%s]\n", str_insert(buf, sizeof buf, "def", 3), buf);

    strcpy(buf, "abc");                             /* 失败用例：位置越界 */
    printf("ret=%d\n", str_insert(buf, sizeof buf, "x", 10));
    printf("ret=%d\n", str_insert(buf, 4, "long-long", 3));  /* 容量不足 */
    return 0;
}
要点：接口带 cap 才能安全拒绝越界；后移必须从后往前（或用 memmove）；写完不越位、不丢结尾符；失败用例（pos 越界 / 容量不足 / 空指针）要能返回错误码。若不喜欢 memmove，可手写后移循环 `for (i = dst_len + 1; i-- > pos; ) dst[i + src_len] = dst[i];`，效果相同。

标准写法：
#define ARRAY_SIZE(array) (sizeof(array) / sizeof((array)[0]))
验证：
#include <stdio.h>
int main(void)
{
    int arr[10] = {0};
    char buf[64];
    printf("%zu %zu\n", ARRAY_SIZE(arr), ARRAY_SIZE(buf));   /* 10 64 */
    return 0;
}
原理与要点：
①`sizeof(数组名)` 得到整个数组的字节数（数组名在 sizeof 内不退化为指针），除以单个元素字节数即元素个数，且与元素类型无关；
②结果在编译期即为常量，可直接用于定义数组维度、静态断言等需要常量表达式的场合；
③参数与宏体都加括号：外层括号防 `ARRAY_SIZE(a) + 1` 之类上下文出错，参数括号可接受 `(p->arr)` 这样的实参；
④只适用于「真数组」——把数组作函数参数传入后形参退化为指针，此时 `sizeof(array)` 只是指针大小（32 位 4），宏会算出错误结果，因此函数内必须额外传入长度参数（或改用 C++ 的 `std::size` / 模板 `template<typename T, size_t N> constexpr size_t size(T (&)[N]) { return N; }` 以保证只接受真数组）。

函数原型为 `char *f(char *s, char c);`，指向它的函数指针声明：
char *(*fp)(char *s, char c);          /* fp 是指向「参数 char* 与 char、返回 char* 的函数」的指针 */
用 typedef 更清晰：
typedef char *(*fn_ptr_t)(char *s, char c);   /* 直接把指针类型起别名 */
fn_ptr_t fp;                                   /* 或一步到位：fn_ptr_t fp = my_func; */
配套的赋值与调用示例：
#include <stdio.h>
#include <string.h>

char *my_strchr2(char *s, char c)      /* 返回 char*、收 char* 与 char 的函数 */
{
    while (*s && *s != c) s++;
    return *s ? s : NULL;
}

int main(void)
{
    char *(*fp)(char *s, char c) = my_strchr2;   /* 函数名自动退化为函数指针 */
    char buf[] = "hello";
    char *r = fp(buf, 'l');                       /* 等价写法：(*fp)(buf, 'l') */
    printf("%s\n", r ? r : "(null)");             /* llo */
    return 0;
}
读法（右左法则）：从 fp 出发先看括号内右侧再向左——`(*fp)` 表明 fp 是指针，右侧 `(char *, char)` 表明它指向函数，最左边的 `char *` 是该函数的返回类型。
要点与易错：
①`char *(*fp)(char *, char);` 才是函数指针；`char *(fp)(char *, char);` 是普通函数声明，fp 是函数不是指针（漏括号就变成「指针函数」——返回指针的函数）；
②术语别混淆：指针函数 = 返回指针的函数；函数指针 = 指向函数的指针；
③应用：回调（qsort 比较器）、驱动接口表、命令分派表（函数指针数组）、插件机制，是 C 语言实现多态的常用手段。

#include <stdio.h>
#include <stddef.h>

/* 与标准库同型：void *memcpy(void *dest, const void *src, size_t n) */
void *my_memcpy(void *dest, const void *src, size_t n)
{
    if (dest == NULL || src == NULL || n == 0)   /* 防御：空指针/零长度 */
        return dest;

    char       *d = (char *)dest;        /* 转成按字节可寻址的指针 */
    const char *s = (const char *)src;

    while (n-- > 0)                      /* 逐字节拷贝，对任意类型都正确 */
        *d++ = *s++;

    return dest;                         /* 返回目标首地址，支持链式调用 */
}

/* 可选加分版：源目标不重叠时按机器字批量搬，尾部逐字节 */
void *my_memcpy_fast(void *dest, const void *src, size_t n)
{
    unsigned char       *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    size_t words = n / sizeof(unsigned long);
    size_t rest  = n % sizeof(unsigned long);
    unsigned long *dw = (unsigned long *)d;   /* 注意：需保证目的地址已对齐 */
    const unsigned long *sw = (const unsigned long *)s;
    while (words--)
        *dw++ = *sw++;
    d = (unsigned char *)dw;
    s = (const unsigned char *)sw;
    while (rest--)
        *d++ = *s++;
    return dest;
}

int main(void)
{
    char src[] = "memcpy test";
    char dst[32] = {0};
    my_memcpy(dst, src, sizeof(src));   /* 连结尾 '\0' 一起拷 */
    printf("%s\n", dst);              /* 输出：memcpy test */
    return 0;
}

#include <stdio.h>
#include <math.h>    /* floor, signbit */

#define IBUF  48                  /* 整数部分数字缓冲（long 最多 19 位，留足余量）*/
#define DBUF  80                  /* 整数 + '.' + 精度位小数 + '\0' */

/* 把 double x 转成十进制字符串写入 buf，保留 prec 位小数（四舍五入），返回 buf */
char *float_to_str(double x, char *buf, int prec)
{
    char   ibody[IBUF];            /* 整数部分数字（低位在前，便于逆序取位）*/
    char   digit[DBUF];            /* 结果数字串：<整数> '.' <prec 位小数> */
    char   frac[16];               /* 小数位数字（字符串形式）*/
    int    ilen = 0, i, k, nd;
    int    neg;
    double ax, ipd, fra, scale;
    long   ip, fv;

    if (prec < 0) prec = 0;
    if (prec > 9) prec = 9;

    /* 1. 符号：必须用 signbit，否则 -0.0 会丢掉负号 */
    neg = signbit(x) ? 1 : 0;
    ax  = neg ? -x : x;

    /* 2. 核心拆分。关键点：小数必须按 10^prec 直接定标取整，
         绝不能先把小数补成“9 位定点”再截断——补零会把有效数字挤掉。
         反例：1.005-1.0 = 0.0049999999999999999，乘 1e9 加 0.5 得 5000000.49999989，
         取整得 5000000，写成 9 位是 005000000，若精度要 2 位就会误读成“第 3 位是 0”。
         正确做法：fra * 10^prec + 0.5 再取整，一步完成本精度的四舍五入。 */
    scale = 1.0;
    for (i = 0; i < prec; i++) scale *= 10.0;      /* scale = 10^prec */

    ipd = floor(ax);
    fra = ax - ipd;
    fv  = (long)(fra * scale + 0.5e0);             /* 小数部分的定标整数 */
    ip  = (long)ipd;
    if (fv >= (long)scale) { ip += 1; fv = 0; }    /* 小数四舍五入进位到整数 */

    /* 3. 整数部分：逆序取位后反转（do-while 保证 0 也输出 '0'）*/
    do { ibody[ilen++] = (char)('0' + ip % 10); ip /= 10; } while (ip > 0);
    for (i = 0; i < ilen; i++) digit[i] = ibody[ilen - 1 - i];

    /* 4. 小数部分：把定标整数 fv 写成恰好 prec 位的字符串（左侧补 '0'）*/
    k = ilen;
    if (prec > 0) {
        nd = 0;
        for (i = 0; i < prec; i++) { frac[i] = (char)('0' + fv % 10); fv /= 10; }
        digit[k++] = '.';
        for (i = prec - 1; i >= 0; i--) { digit[k++] = frac[i]; nd++; }
        if (nd != prec) return NULL;              /* 不可能发生，防御性检查 */
    }
    digit[k] = '\0';

    /* 5. 加符号并封口 */
    k = 0;
    if (neg) buf[k++] = '-';
    for (i = 0; digit[i]; i++) buf[k++] = digit[i];
    buf[k] = '\0';
    return buf;
}

int main(void)
{
    char buf[64];
    printf("%s\n", float_to_str(1234.56789, buf, 4));  /* 1234.5679 */
    printf("%s\n", float_to_str(-3.5,      buf, 4));  /* -3.5000  */
    printf("%s\n", float_to_str(0.0,       buf, 2));  /* 0.00     */
    printf("%s\n", float_to_str(-0.0,      buf, 2));  /* -0.00（靠 signbit）*/
    printf("%s\n", float_to_str(0.5,       buf, 2));  /* 0.50     */
    printf("%s\n", float_to_str(9.999,     buf, 2));  /* 10.00（小数进位到整数）*/
    printf("%s\n", float_to_str(99.996,    buf, 2));  /* 100.00（整数段也进位）*/
    printf("%s\n", float_to_str(0.0,       buf, 0));  /* 0（prec=0）*/
    printf("%s\n", float_to_str(1.005,     buf, 2));  /* 1.00（与 %.2f 一致）*/
    printf("%s\n", float_to_str(8.015,     buf, 2));  /* 8.02（二进制值确实偏大）*/
    return 0;
}
运行输出（与 glibc 的 %.Nf 逐条一致）：
  1234.5679 / -3.5000 / 0.00 / -0.00 / 0.50 / 10.00 / 100.00 / 0 / 1.00 / 8.02
说明：① 1.005 的二进制值是 1.0049999999999999，所以 %.2f 给 1.00 而不是 1.01，本实现按 fra*10^prec+0.5 取整，得到同样结果（这正是替学生常答错的地方）；② 示例 1234.56789 的二进制值约为 1234.5678899999999，直接取 5 位小数会得到 ...56788，故按 4 位精度输出 1234.5679；③ 若必须逐位精确匹配十进制字面量，可直接调用
snprintf(buf, sizeof buf, "%.5f", 1234.56789)，标准库会用十进制最优表示给出期望串。

#include <stdio.h>
#include <string.h>

/* 反转 s[left..right]（闭区间） */
static void reverse_range(char *s, int left, int right)
{
    while (left < right) {
        char t   = s[left];
        s[left]  = s[right];
        s[right] = t;
        left++;
        right--;
    }
}

/* 原地把字符串 s 循环右移 n 位，返回 s；三次反转法：时间 O(L)、空间 O(1) */
char *str_rotate_right(char *s, int n)
{
    int len = (int)strlen(s);
    int k;

    if (s == NULL || len == 0) return s;   /* 空串直接返回 */

    k = n % len;                           /* 右移超过一圈先取模 */
    if (k < 0) k += len;                   /* 支持负数 = 左移 */
    if (k == 0) return s;                  /* 无需移动 */

    reverse_range(s, 0, len - k - 1);      /* 前 len-k 个反转 */
    reverse_range(s, len - k, len - 1);    /* 后 k 个反转     */
    reverse_range(s, 0, len - 1);          /* 整体反转        */
    return s;
}

int main(void)
{
    char s[] = "abcdefghi";
    printf("%s\n", str_rotate_right(s, 2));   /* 输出：hiabcdefg   */

    { char t[] = "abcdefghi"; printf("%s\n", str_rotate_right(t, 9)); }  /* abcdefghi（原样）*/
    { char t[] = "abcdefghi"; printf("%s\n", str_rotate_right(t, 11)); } /* 11%9=2 -> hiabcdefg */
    { char t[] = "abcdefghi"; printf("%s\n", str_rotate_right(t, 0)); }  /* abcdefghi */
    { char t[] = "";          printf("[%s]\n", str_rotate_right(t, 3)); } /* [] 空串安全 */
    return 0;
}

#include <stdio.h>

/* 统计数组 a 中大于等于平均值的元素个数；n<=0 返回 0 */
int count_ge_average(const int *a, int n)
{
    long long sum = 0;      /* 用 64 位累加，防止求和溢出 */
    double    avg;
    int       i, cnt = 0;

    if (a == NULL || n <= 0) return 0;

    for (i = 0; i < n; i++)
        sum += a[i];

    avg = (double)sum / (double)n;   /* 必须浮点除法，否则边界判错 */

    for (i = 0; i < n; i++)
        if ((double)a[i] >= avg)     /* 题目要求“大于等于” */
            cnt++;

    return cnt;
}

/* ---------- 验证函数：独立实现一遍并返回平均值，便于打印核对 ---------- */
int verify(const int *a, int n, int expect, double *avg_out)
{
    long long sum = 0;
    int       i, cnt = 0;
    double    avg;

    if (a == NULL || n <= 0) { if (avg_out) *avg_out = 0.0; return expect == 0; }

    /* 用 long double 独立重算，避免与被测函数共用同一段代码逻辑 */
    for (i = 0; i < n; i++) sum += (long long)a[i];
    avg = (double)((long double)sum / (long double)n);
    for (i = 0; i < n; i++) if ((double)a[i] >= avg) cnt++;

    if (avg_out) *avg_out = avg;
    if (cnt != expect) {
        printf("[FAIL] 期望 %d，实际 %d（平均值 %.4f）\n", expect, cnt, avg);
        return 0;
    }
    return 1;   /* 通过 */
}

/* 测试用例：覆盖普通、全相等、全不等、负数、单元素、空数组 */
static void run_case(const char *name, const int *a, int n, int expect)
{
    double avg = 0.0;
    int got = count_ge_average(a, n);
    int ok  = verify(a, n, expect, &avg);
    printf("%-14s n=%d avg=%8.4f 结果=%d 期望=%d %s\n",
           name, n, avg, got, expect,
           (ok && got == expect) ? "PASS" : "FAIL");
}

int main(void)
{
    int a1[] = {1, 2, 3, 4};        /* avg=2.5，>=2.5 的有 3,4 -> 2 */
    int a2[] = {5, 5, 5};           /* avg=5.0，全 >=     -> 3 */
    int a3[] = {1, 2};              /* avg=1.5，>=1.5 的只有 2 -> 1 */
    int a4[] = {-3, -1, 4};         /* avg=0.0，>=0 的只有 4 -> 1 */
    int a5[] = {7};                 /* avg=7.0，>=7 -> 1 */

    run_case("mixed",   a1, 4, 2);
    run_case("equal",   a2, 3, 3);
    run_case("intdiv",  a3, 2, 1);   /* 若用整数除法会错算成 2 */
    run_case("negative",a4, 3, 1);
    run_case("single",  a5, 1, 1);
    run_case("empty",   a5, 0, 0);
    return 0;
}

#include <stdio.h>
#include <assert.h>

/* 判断整数 v 的十进制表示中是否含有数字 6 */
static int digit_has_6(long v)
{
    if (v < 0) v = -v;
    do {
        if (v % 10 == 6) return 1;
        v /= 10;
    } while (v > 0);          /* do-while 保证 0 也能判一次 */
    return 0;
}

/* 统计 [0, n] 中能被 6 整除、或十进制含有 6 的整数个数 */
long count_valid(long n)
{
    long i, cnt = 0;
    if (n < 0) return 0;                 /* 防御非法输入 */
    for (i = 1; i <= n; i++)             /* 从 1 计数；若要含 0 则从 0 开始 */
        if ((i % 6 == 0) || digit_has_6(i))
            cnt++;
    return cnt;
}

/* 验证用：数学分解计数 ——
   |A∪B| = |A| + |B| - |A∩B|
   A = 能被 6 整除的个数 = n/6
   B = 含 6 的个数（下面按位统计）
   A∩B = 能被 6 整除且含 6 的个数（再暴力一遍，规模小）*/
static long count_has6_only(long n)      /* 仅统计含 6 的个数 */
{
    long i, c = 0;
    for (i = 1; i <= n; i++) c += digit_has_6(i);
    return c;
}

static long count_both(long n)           /* 同时满足两个条件的个数 */
{
    long i, c = 0;
    for (i = 1; i <= n; i++) c += (i % 6 == 0) && digit_has_6(i);
    return c;
}

static long verify(long n)
{
    return n / 6 + count_has6_only(n) - count_both(n);   /* 容斥原理 */
}

int main(void)
{
    long n;

    /* 手工可核对的边界值 */
    assert(count_valid(0)   == 0);    /* 区间内无正整数 */
    assert(count_valid(1)   == 0);
    assert(count_valid(6)   == 1);    /* 6：既能被 6 整除又含 6，只算一次 */
    assert(count_valid(12)  == 2);    /* 6, 12 */
    assert(count_valid(16)  == 3);    /* 6, 12, 16（16 含 6）*/
    assert(count_valid(60)  == 14);   /* 被 6 整除 10 个 + 含数字 6 的 16/26/46/56 共 4 个 = 14 */

    /* 容斥验证：两个独立实现必须一致 */
    for (n = 0; n <= 100000; n += 997)   /* 抽样覆盖全域 */
        assert(count_valid(n) == verify(n));

    printf("count_valid(100000) = %ld\n", count_valid(100000));
    printf("verify(100000)      = %ld\n", verify(100000));
    printf("全部断言通过\n");
    return 0;
}
结果自检：n=100000 时 |A|（能被 6 整除）= 100000/6 = 16666；
  |B|（十进制含 6）可用补集算：不含数字 6 的 0~99999（把 0~99999 看成 5 位、允许前导零）共有 9^5 = 59049 个，
  故 |B| = 100000 - 59049 = 40951；
  |A∩B|（既能被 6 整除又含 6）由 count_both 暴力得出（约 7000 左右），
  最终 |A∪B| = |A| + |B| - |A∩B| ≈ 16666 + 40951 - |A∩B| ≈ 5 万级，远小于 int 上限，用 long 只是保险。
  程序会打印 count_valid(100000) 与 verify(100000)，两者必须相等，这就是本题的自验证。
性能加分：把 digit_has_6 换成位技巧（对 x 做 (x + 0x22222222u) 观察 0x88888888u 位进位传播），可把内层循环压成常数条指令，10 万次规模提升数倍，但须能清楚解释进位原理。
